#include <cstdint>
#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
#include <stdexcept>
using R=std::vector<unsigned>;using U=std::uint64_t;void need(bool x,const char*s){if(!x)throw std::runtime_error(s);}
U H(const R&a){unsigned n=a.size(),N=1u<<n;std::vector<U>d(size_t(N)*n);for(unsigned u=0;u<n;u++)d[size_t(1u<<u)*n+u]=1;for(unsigned mask=1;mask<N;mask++)for(unsigned u=0;u<n;u++){auto z=d[size_t(mask)*n+u];if(!z)continue;unsigned next=a[u]&~mask;while(next){unsigned b=next&-next;next-=b;d[size_t(mask|b)*n+__builtin_ctz(b)]+=z;}}U out=0;for(unsigned u=0;u<n;u++)out+=d[size_t(N-1)*n+u];return out;}
std::vector<std::int64_t> profile(const R&a){unsigned n=a.size();std::vector<std::int64_t>q(n+2);std::vector<unsigned>p(n);std::iota(p.begin(),p.end(),0);do{unsigned backward=0;for(unsigned i=0;i+1<n;i++)if(!(a[p[i]]&(1u<<p[i+1])))backward|=1u<<i;for(unsigned cuts=0;cuts<(1u<<(n-1));cuts++)if((cuts&backward)==backward)q[1+__builtin_popcount(cuts)]++;}while(std::next_permutation(p.begin(),p.end()));return q;}
R tt(unsigned n){R a(n);for(unsigned i=0;i<n;i++)for(unsigned j=i+1;j<n;j++)a[i]|=1u<<j;return a;}
R core(const R&a,bool reverse){unsigned n=a.size();R out(3*n);for(unsigned i=0;i<3;i++)for(unsigned u=0;u<n;u++){unsigned row=a[u];if(reverse&&i!=1)row^=((1u<<n)-1)^(1u<<u);out[i*n+u]|=row<<(i*n);unsigned j=(i+(reverse?2:1))%3;out[i*n+u]|=((1u<<n)-1)<<(j*n);}return out;}
R substitute(const R&Q,const R&core){unsigned m=core.size();R a=core;a.resize(m+Q.size()-1);for(unsigned j=1;j<Q.size();j++){unsigned v=m+j-1;if(Q[0]&(1u<<j))for(unsigned u=0;u<m;u++)a[u]|=1u<<v;else a[v]|=(1u<<m)-1;for(unsigned k=1;k<Q.size();k++)if(Q[j]&(1u<<k))a[v]|=1u<<(m+k-1);}return a;}
R ports(R a,unsigned aa,unsigned cc){unsigned x=a.size(),y=x+1;a.push_back(1u<<y);a.push_back(0);for(unsigned u=0;u<x;u++){if(aa&(1u<<u))a[u]|=1u<<x;else a[x]|=1u<<u;if(cc&(1u<<u))a[u]|=1u<<y;else a[y]|=1u<<u;}return a;}
void rows(const R&a){std::cout<<"[";for(unsigned i=0;i<a.size();i++){if(i)std::cout<<",";std::cout<<a[i];}std::cout<<"]";}
int main(){std::vector<R>children={tt(1),tt(2),tt(3),R{2,4,1},tt(4),R{8,1,3,6}};std::vector<R>contexts={R{0},R{2,0},R{0,1},R{2,4,1},R{6,4,0},R{6,12,24,17,3}};bool first=true;unsigned count=0;std::cout<<"{\"status\":\"PASS\",\"records\":[";for(unsigned ci=0;ci<children.size();ci++){const R&a=children[ci];auto q=profile(a);std::int64_t P=0;for(unsigned j=1;j<q.size()-1;j++)P+=j*(q[j+1]+2*q[j])*(q[j]*q[j]-q[j-1]*q[j+1]);need(P>0,"scalar strictness");for(unsigned oi=0;oi<contexts.size();oi++){const R&Q=contexts[oi];unsigned n=a.size(),m=3*n,aa=(1u<<n)-1,cc=((1u<<n)-1)<<n;for(unsigned j=1;j<Q.size();j++)if(Q[j]&1u){aa|=1u<<(m+j-1);cc|=1u<<(m+j-1);}R T=substitute(Q,core(a,false)),Urows=substitute(Q,core(a,true));U f=H(ports(T,aa,cc)),g=H(ports(Urows,aa,cc)),lower=H(Q)*U(P);need(g>f&&g-f>=lower,"strict ambient sign and lower bound");if(!first)std::cout<<",";first=false;std::cout<<"{\"child_index\":"<<ci<<",\"context_index\":"<<oi<<",\"child_rows\":";rows(a);std::cout<<",\"outer_rows\":";rows(Q);std::cout<<",\"source_old_rows\":";rows(T);std::cout<<",\"target_old_rows\":";rows(Urows);std::cout<<",\"a\":"<<aa<<",\"c\":"<<cc<<",\"F_source\":"<<f<<",\"F_target\":"<<g<<",\"target_minus_source\":"<<g-f<<",\"lower_bound\":"<<lower<<"}";count+=2;}}std::cout<<"],\"physical_queries\":"<<count<<"}\n";}
